// Keeps the header nav and footer of the scraped pages (homepage, FAQ, contact,
// booking, Phuket tour pages) in step with the homepage. The region pages are
// generated by build-region-pages.js and already share this link set.
const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");
const catalog = JSON.parse(
  fs.readFileSync(path.join(root, "data", "region-tours.json"), "utf8")
);

// Pages produced by build-region-pages.js — skip, they are built from source.
const GENERATED = new Set(
  ["destinations/index.html", "credits/index.html", "how-to-book/index.html"].concat(
    catalog.flatMap((r) =>
      ["destinations/" + r.region + "/index.html"].concat(
        r.tours.map((t) => "tours/" + t.slug + "/index.html")
      )
    )
  )
);

const FOOTER_LINK_CLASS = "text-white/70 hover:text-white";
const MAP_URL =
  "https://www.google.com/maps/dir/19.9753728,99.8703104/13.75101,100.83938/@16.8331169,97.6363631,7z/data=!3m1!4b1!4m4!4m3!1m1!4e1!1m0?entry=ttu&g_ep=EgoyMDI2MDkwMi4wIKXMDSoASAFQAw%3D%3D";

const EXPLORE = [
  ["index.html", "Home"],
  ["index.html#popular", "Tours"],
  ["faq/", "FAQ"],
  ["contact/", "Contact Us"],
  ["how-to-book/", "How to book"],
  ["index.html#how-booking-works", "How booking works"],
  ["index.html#credentials", "Credentials"],
];

const DESTINATIONS = [
  ["destinations/chiang-mai/", "Chiang Mai"],
  ["destinations/chiang-rai/", "Chiang Rai"],
  ["destinations/krabi/", "Krabi"],
  ["destinations/koh-samui/", "Koh Samui"],
  ["index.html#popular", "Phuket tours"],
  ["destinations/", "All destinations"],
];

const CONTACT = [
  [MAP_URL, "852/7 พฤกษา อเวนิว Thap Yao, Lat Krabang, Bangkok 10520", true],
  ["tel:+66842148155", "084 214 8155"],
  ["tel:+66821479553", "082 147 9553"],
  ["https://line.me/R/ti/p/~@354ejhoo", "Line @354ejhoo", true],
  ["http://m.me/dgholidaythailand", "Messenger", true],
  ["mailto:dgholidaythailand@gmail.com", "dgholidaythailand@gmail.com"],
  ["https://wa.me/66821479553", "WhatsApp", true],
];

function listItems(items, prefix, absolute) {
  return items
    .map(([href, label, external]) => {
      const url = absolute ? href : prefix + href;
      const attrs = external ? ' target="_blank" rel="noopener noreferrer"' : "";
      return `\n          <li><a class="${FOOTER_LINK_CLASS}" href="${url}"${attrs}>${label}</a></li>`;
    })
    .join("");
}

function replaceColumn(footer, heading, items, prefix, absolute) {
  const re = new RegExp(
    ">" + heading + "</h2>([\\s\\S]*?<ul[^>]*>)[\\s\\S]*?(</ul>)"
  );
  if (!re.test(footer)) return { footer, ok: false };
  return {
    footer: footer.replace(
      re,
      (m, openTag, closeTag) =>
        ">" + heading + "</h2>" + openTag + listItems(items, prefix, absolute) + "\n        " + closeTag
    ),
    ok: true,
  };
}

function pages() {
  const found = [];
  (function walk(dir) {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      if (
        entry.name.startsWith(".") ||
        entry.name === "node_modules" ||
        entry.name === "_docx_tmp"
      )
        continue;
      const p = path.join(dir, entry.name);
      if (entry.isDirectory()) walk(p);
      else if (entry.name === "index.html") found.push(p);
    }
  })(root);
  return found;
}

let patchedNav = 0;
let patchedFooter = 0;

for (const file of pages()) {
  const rel = path.relative(root, file).replace(/\\/g, "/");
  if (GENERATED.has(rel)) continue;

  const depth = rel.split("/").length - 1;
  const prefix = "../".repeat(depth);
  let html = fs.readFileSync(file, "utf8");
  const before = html;

  /* 1. "How to book" in the desktop and mobile nav, before FAQ. */
  const footerStart = html.lastIndexOf("<footer");
  if (!html.includes(`href="${prefix}how-to-book/"`)) {
    const navItem = new RegExp(
      `<li><a class="([^"]*)" href="${prefix.replace(/\./g, "\\.")}faq/">FAQ</a></li>`,
      "g"
    );
    html = html.replace(navItem, (match, cls, offset) => {
      if (footerStart > 0 && offset > footerStart) return match;
      return (
        `<li><a class="${cls}" href="${prefix}how-to-book/">How to book</a></li>` + match
      );
    });
    if (html !== before) patchedNav += 1;
  }

  /* 2. Footer columns. */
  const fStart = html.lastIndexOf("<footer");
  const fEnd = html.indexOf("</footer>", fStart);
  if (fStart >= 0 && fEnd > fStart) {
    let footer = html.slice(fStart, fEnd);
    const footerBefore = footer;
    let res = replaceColumn(footer, "Explore", EXPLORE, prefix, false);
    footer = res.footer;
    res = replaceColumn(footer, "Destinations", DESTINATIONS, prefix, false);
    footer = res.footer;
    res = replaceColumn(footer, "Contact", CONTACT, prefix, true);
    footer = res.footer;
    if (footer !== footerBefore) {
      html = html.slice(0, fStart) + footer + html.slice(fEnd);
      patchedFooter += 1;
    }
  }

  if (html !== before) {
    fs.writeFileSync(file, html, "utf8");
    console.log("synced", rel);
  }
}

console.log("nav patched:", patchedNav, "| footers patched:", patchedFooter);
